//! Agent guidance for integrated HTML reports. The marker and variable names
//! are the contract implemented by the app's inline HTML view.

pub(crate) const REPORT_GUIDANCE: &str = "Grove renders compact, focused HTML visuals inline in the conversation without a toolbar. Keep inline content small and discernible in a chat transcript; link large documents as [Open in browser](path/to/document.html) to open externally without an inline preview. When referencing an inline document in a later reply, include its link again so it renders in that reply. When a visual report, chart, dashboard or comparison communicates better than prose, write one complete, self-contained HTML document (inline CSS and JavaScript, data: URLs only; network and file requests are blocked) as a fenced block tagged html, whose content starts with <!doctype html>, or as a local .html file linked in Markdown. Include the exact comment <!-- grove:integrated-report --> inside the document, after the doctype, so Grove themes it and sizes it to its content. Style it with Grove's CSS variables instead of fixed colours: --grove-bg, --grove-fg, --grove-muted, --grove-surface, --grove-border, --grove-info, --grove-success, --grove-warning, --grove-font, --grove-body, --grove-title, --grove-display, --grove-gap, --grove-section and --grove-radius. Avoid viewport-height layouts, inner scroll areas, fixed or sticky positioning, and body margins. Prefer prose for answers that do not need a visual. Prefer grove_visuals.preview_html and render_html for new durable visuals when available; these save snapshots beside the tool event while older fenced/link previews retain their behavior.";

const EXPLICIT_GUIDANCE: &str = "Grove publishes HTML artifacts only through grove_visuals.render_html in this conversation. HTML fences remain code and HTML file links open the file viewer. For a useful chart, comparison or interactive visual, create one complete offline HTML document, then call preview_html for a native screenshot and inspect it before render_html. Both tools take exactly one of inline html or an absolute local path, title and a unique request_id; use distinct IDs for preview and publication. Host file/image reads require effective bypass permissions and registered roots; otherwise pass inline HTML with data assets. Inline CSS, JavaScript, fonts and SVG. Network and file requests are blocked. Publication saves an immutable snapshot attached to its tool event; revisions require visual_id and a new request_id. Use Grove theme variables (--grove-bg, --grove-fg, --grove-muted, --grove-surface, --grove-border, --grove-info, --grove-success, --grove-warning, --grove-font, --grove-body, --grove-title, --grove-display, --grove-gap, --grove-section, --grove-radius). Set presentation to inline for a small chart, dashboard for a responsive dashboard, canvas for a pan/zoom workspace, or document for a long report. The default is dashboard. Every published HTML document is called an artifact and appears as a single-line transcript row; the reader opens its dedicated viewer for live interaction. No presentation mode embeds live HTML or an automatic screenshot in the transcript. Width/height set the layout viewport, not transcript size. Use a desktop viewport for dashboards rather than stretching them with chat width. Canvas authors own pan/zoom and fit-to-content; preview_region supplies world-space x/y/width/height via the one-time grove:initial-view DOM event detail.frame. Handle it to fit the camera, and retain camera state across resize. Agent-requested document previews show their opening section or a preview_region scroll target. Use viewport-height layouts only inside full-view dashboards/canvases. Native capture can be unavailable without blocking publication; report unchecked previews truthfully. Child-agent publication without reliable root tool ownership is unsupported. Prefer prose when no visual is needed. Use Open in browser links for external-only documents.";
pub(crate) fn guidance(policy: crate::visuals::HtmlPolicy) -> &'static str {
    match policy {
        crate::visuals::HtmlPolicy::Explicit => EXPLICIT_GUIDANCE,
        crate::visuals::HtmlPolicy::Legacy => REPORT_GUIDANCE,
    }
}
